using System.ComponentModel.DataAnnotations;
using DineFlow.Application.Promotions;
using DineFlow.Domain.Payments;

namespace DineFlow.Application.Payments;

/// <param name="ClientRequestId">Generated by the guest app per attempt and reused on retry.</param>
/// <param name="Mode">What the guest is paying: the rest of the bill, equal shares, their items or an amount.</param>
/// <param name="Shares">Equal split: how many people this guest pays for.</param>
/// <param name="AmountMinor">Custom amount, inclusive of taxes and charges, before tip and discount.</param>
/// <param name="ExpectedAmountMinor">The share of the bill the guest saw; if it changed, nothing is charged.</param>
/// <param name="AcceptTerms">The guest agreed to the Terms and Conditions shown next to the pay button.</param>
public record CreatePaymentRequest(
    [Required] Guid SessionId,
    [Required] Guid ClientRequestId,
    [Required] PaymentMethod Method,
    PaymentMode Mode,
    [Range(1, 50)] int? Shares,
    [Range(1, 100_000_000)] long? AmountMinor,
    [Range(0, 100_000_000)] long TipMinor,
    [StringLength(20)] string? PromoCode,
    [Range(1, 100_000_000)] long ExpectedAmountMinor,
    bool AcceptTerms);

public record ReceiptRequest([Required, EmailAddress, StringLength(254)] string Email);

/// <summary>A payment as the guest sees it, plus where the bill stands and an offer once it has succeeded.</summary>
public record PaymentDto(
    Guid Id,
    string Reference,
    PaymentStatus Status,
    PaymentMethod Method,
    PaymentMode Mode,
    int? Shares,
    int? SplitPeople,
    /// <summary>Items this payment covers when splitting by item.</summary>
    int ItemCount,
    string Currency,
    long BillAmountMinor,
    long DiscountMinor,
    long TipMinor,
    long AmountMinor,
    string? PromoCode,
    string? CardBrand,
    string? CardLast4,
    string? FailureReason,
    /// <summary>The provider's page to send the guest to while the payment needs their action.</summary>
    string? CheckoutUrl,
    string LocationType,
    string LocationLabel,
    string? AreaName,
    string? AreaNameAr,
    DateTimeOffset CreatedAt,
    DateTimeOffset? SucceededAt,
    /// <summary>What's still owed on the bill after this payment (known once it succeeded).</summary>
    long? RemainingMinor,
    bool? FullyPaid,
    NextVisitOfferDto? NextVisitOffer,
    /// <summary>The venue asks for a rating and this paid visit hasn't been rated yet.</summary>
    bool CanReview,
    /// <summary>The rating this guest gave, once they have.</summary>
    int? ReviewRating);
